import json,csv,html,hashlib
from pathlib import Path
P=Path(__file__).resolve().parents[1]
rows=list(csv.DictReader((P/'results/powerbi_export/V2_ActionQueue.csv').open(encoding='utf8')))
inc=list(csv.DictReader((P/'results/INC002_Vorher_Nachher.csv').open()))
wms=list(csv.DictReader((P/'results/INC002_WMS_Retest_Evidenz.csv').open()))
assert len(rows)==500 and len(inc)==2 and len(wms)==1
# This is a ready-to-run, entirely offline browser app with actionable filtering; not a Power BI screenshot.
def js(x):return json.dumps(x,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e')
page=r'''<!doctype html><html lang="de"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Phase 6 — Data Quality Command Center</title>
<style>
:root{--bg:#0b1422;--panel:#142238;--panel2:#1b2b43;--stroke:#2d3e55;--white:#f5f9ff;--muted:#9fb0c6;--blue:#43c1f2;--orange:#f4b85e;--red:#f17f83;--green:#57d9b0}*{box-sizing:border-box}body{background:var(--bg);color:var(--white);margin:0;font-family:Inter,system-ui,Segoe UI,sans-serif;font-size:14px}header{background:linear-gradient(135deg,#142a45,#0b1422 75%);border-bottom:1px solid var(--stroke);padding:32px max(24px,calc((100vw - 1450px)/2))}.eyebrow{color:var(--blue);font-size:11px;letter-spacing:2px;font-weight:800;text-transform:uppercase}h1{font-size:clamp(26px,4vw,42px);letter-spacing:-.9px;margin:10px 0 8px}h2{font-size:20px;margin:0 0 14px}h3{font-size:14px;margin:0 0 10px}.sub{color:var(--muted);max-width:800px;line-height:1.5}.accent{color:var(--blue)}main{max-width:1450px;margin:auto;padding:24px}.badge{display:inline-block;color:#e1eefa;border:1px solid #41556a;padding:5px 10px;border-radius:18px;margin-right:8px;font-size:11px}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:13px;margin:15px 0 24px}.metric,.panel{background:var(--panel);border:1px solid var(--stroke);border-radius:12px}.metric{padding:20px;min-height:120px}.metric b{display:block;font-size:30px;margin:11px 0 6px;font-variant-numeric:tabular-nums}.metric .label{color:var(--muted);font-size:12px}.metric.critical{border-top:3px solid var(--red)}.metric.warn{border-top:3px solid var(--orange)}.metric.ok{border-top:3px solid var(--green)}.panel{padding:20px;margin-bottom:18px}.tools{display:grid;grid-template-columns:1.6fr 1fr 1fr auto auto;gap:10px;align-items:end}label{display:block;color:var(--muted);font-size:12px;margin:0 0 6px}select,input[type=search],button{background:#0e1c30;color:var(--white);border:1px solid #456079;border-radius:7px;padding:10px;font:inherit;min-height:40px}input[type=search]{width:100%}button{cursor:pointer}button:hover{border-color:var(--blue)}button.primary{background:#176089;border-color:#2782b0;font-weight:600}.check{white-space:nowrap;color:#c9d6e4}.check input{margin-right:6px}.workspace{display:grid;grid-template-columns:minmax(0,2fr) minmax(320px,1fr);gap:18px}.scroll{overflow:auto;max-height:570px}.row{display:flex;align-items:center;justify-content:space-between;margin:12px 0;gap:18px}.hint{color:var(--muted);font-size:12px}.pill{border-radius:6px;padding:4px 7px;font-weight:700;font-size:11px;white-space:nowrap}.p1{background:#482633;color:#ffb5b5}.p2{background:#433820;color:#ffd28c}.p3{background:#254161;color:#a9daff}.p0{background:#233e35;color:#9aebc7}table{border-collapse:collapse;width:100%;font-size:12px}th{position:sticky;top:0;background:#1a2c43;z-index:1;color:#bccbdc;text-align:left}td,th{padding:12px 9px;border-bottom:1px solid #293c53}tr[data-sku]{cursor:pointer}tr[data-sku]:hover{background:#213950}tr.selected{background:#244b5d}.mono{font-variant-numeric:tabular-nums;font-family:ui-monospace,Consolas,monospace}.chips{display:flex;gap:9px;flex-wrap:wrap}.chip{border-radius:5px;background:#233449;padding:6px 8px;color:#d0dfee;font-size:12px}.details-row{border-bottom:1px solid #30445c;padding:10px 0}.details-row span{color:var(--muted);display:block;font-size:12px}.details-row strong{display:block;font-size:13px;margin-top:4px;overflow-wrap:anywhere}.bar{display:flex;align-items:center;gap:9px;margin:12px 0}.barlabel{width:145px;font-size:11px;color:var(--muted)}.track{height:13px;flex:1;background:#26364d;border-radius:3px;overflow:hidden}.fill{height:100%;background:var(--blue);border-radius:3px}.barvalue{min-width:36px;text-align:right}.inc{display:grid;grid-template-columns:1fr 1fr;gap:15px}.infobox{background:#0d2030;border-left:3px solid var(--blue);padding:15px;border-radius:5px;line-height:1.6}.warning{border-left-color:var(--orange)}.test{font-size:23px;margin:7px 0}.footer{color:var(--muted);line-height:1.6;font-size:12px;margin-top:24px}.pages{display:flex;align-items:center;justify-content:space-between;margin-top:10px}@media(max-width:1100px){.metrics{grid-template-columns:repeat(3,1fr)}.workspace{grid-template-columns:1fr}.tools{grid-template-columns:1fr 1fr}}@media(max-width:650px){.metrics{grid-template-columns:1fr 1fr}.tools{grid-template-columns:1fr}.inc{grid-template-columns:1fr}header{padding:28px 20px}main{padding:12px}}
</style></head><body><header><div class="eyebrow">Portfolio-Projekt 1 · Phase 6 · Funktionale Erweiterung</div><h1>Data Quality <span class="accent">Command Center</span></h1><p class="sub">Interaktive Maßnahmensteuerung und Incident-Revalidierung · 500 synthetische Artikel · Historischer V2-Stand und getrennte INC-002-Sandbox. Keine echten Unternehmensdaten.</p><span class="badge">Offline nutzbar</span><span class="badge">Filter · Drilldown · CSV-Export</span><span class="badge">Kein automatischer Freigabeentscheid</span></header><main>
<section class="metrics"><article class="metric"><span class="label">Artikel im Filter</span><b id="k-total">—</b><span class="hint">Basis: 500 SKU</span></article><article class="metric warn"><span class="label">Mit Prüfsignal</span><b id="k-signal">—</b><span class="hint">Über Kontrollen hinweg</span></article><article class="metric critical"><span class="label">P1 · Migration / Freigabe</span><b id="k-p1">—</b><span class="hint">Kritisch zu prüfen</span></article><article class="metric warn"><span class="label">Prüfsignal ohne SKU-Fall</span><b id="k-unassigned">—</b><span class="hint">Kein automatisch neuer Incident</span></article><article class="metric ok"><span class="label">Ohne zusätzliches Prüfsignal</span><b id="k-clean">—</b><span class="hint">Nur im Umfang der Matrix</span></article></section>
<section class="panel"><h2>Filtern und untersuchen</h2><div class="tools"><div><label for="search">Artikel / Fehler / Prozessstatus</label><input id="search" type="search" placeholder="HYG-1006, MISSING_TARGET, Freigabe …"></div><div><label for="group">Produktgruppe</label><select id="group"><option value="">Alle Gruppen</option></select></div><div><label for="priority">Priorität</label><select id="priority"><option value="">Alle Prioritäten</option><option value="P1">P1 – Freigabekonflikt</option><option value="P2">P2 – ungeklärtes Signal</option><option value="P3">P3 – verknüpfter Fall</option><option value="P0">P0 – ohne Signal</option></select></div><div class="check"><label><input type="checkbox" id="onlySignal">Nur Prüfsignale</label><button id="reset">Zurücksetzen</button></div><div><label>Export</label><button class="primary" id="export">Gefilterte CSV</button></div></div><p class="hint">P1–P3 sind fachliche Vorschläge, nicht tatsächliche Arbeitsaufträge oder belegte Vermögensschäden. Prüfsignal ≠ bestätigte Ursache.</p></section>
<div class="workspace"><section class="panel"><div class="row"><h2>Priorisierte Artikelliste</h2><span id="table-count" class="hint">—</span></div><div class="scroll"><table aria-label="Aktionsliste"><thead><tr><th>SKU</th><th>Priorität</th><th>DQ01</th><th>DQ02</th><th>DQ06</th><th>Prüffelder</th><th>Fälle</th></tr></thead><tbody id="body"></tbody></table></div><div class="pages"><button id="prev">← Zurück</button><span id="pagination" class="hint">—</span><button id="next">Weiter →</button></div></section><aside class="panel"><h2>Artikel-Drilldown</h2><div id="detail" class="hint">Wähle links einen Artikel aus, um Befund, vorgeschlagene Maßnahme und Verantwortungsbereich einzusehen.</div><div id="review-form" style="display:none;margin-top:15px;padding:13px;background:#0e1c30;border-radius:8px;border:1px solid #34506a"><h3>Eigene Bearbeitung · lokaler Arbeitsstand</h3><label for="review-status">Status</label><select id="review-status" style="width:100%"><option value="NEU">NEU</option><option value="IN_PRUEFUNG">IN_PRUEFUNG</option><option value="RUECKFRAGE">RUECKFRAGE</option><option value="DOKUMENTIERT">DOKUMENTIERT</option></select><label for="review-note" style="margin-top:10px">Notiz</label><textarea id="review-note" maxlength="1500" rows="3" style="width:100%;background:#0e1c30;color:#fff;border:1px solid #456079;border-radius:6px;padding:9px"></textarea><button id="save-review" class="primary" style="margin-top:10px">Lokalen Prüfstand speichern</button><div id="review-message" class="hint" style="margin-top:8px"></div></div><div style="margin-top:24px"><h3>Prioritätsverteilung im aktuellen Filter</h3><div id="bars"></div></div></aside></div>
<section class="panel"><h2>INC-002 · Korrektur und abhängiger WMS-Gate-Test</h2><p class="sub">Getrennter Pilot-Snapshot, NICHT Bestandteil des 500-Artikel-V2-Datenbestands. Die Ausgangsdaten und die historischen 32 offenen V2-Incidents bleiben unangetastet.</p><div class="tools" style="grid-template-columns:280px 1fr"><div><label for="stage">Simulationsstand wählen</label><select id="stage"><option value="BEFORE">S2 · Vor der Korrektur</option><option value="AFTER">S3 · Nach der Korrektur</option></select></div><div class="hint">S2: 15.09.2026 · S3: 19.09.2026 · nur synthetischer WMS-Stub, keine reale ERP-/WMS-Anbindung</div></div><div class="inc" style="margin-top:18px"><div class="infobox" id="incident"></div><div class="infobox warning"><div class="eyebrow" style="color:var(--orange)">Gate-Regel</div><p>Ein Incident wird erst im <strong>isolierten Sandbox-Modell</strong> geschlossen, wenn die Korrektur genehmigt und angewendet wurde, DQ02 erneut bestanden ist, eine simulierte WMS-ACK-Antwort vorliegt und alle vorgesehenen Evidenzen abgelegt wurden.</p><div class="hint" id="wmsevidence"></div></div></div></section>
<div class="footer">Datenherkunft: sieben SQL-Kontrollen des Portfolios; V2_Artikeluebergreifende_Pruefmatrix.csv, V2_ActionQueue.csv, INC002_Vorher_Nachher.csv, INC002_WMS_Retest_Evidenz.csv. Prioritäten/Owners sind neu abgeleitete Empfehlungen. Ohne Browser-Server, ohne Internetverbindung nutzbar. Für native Power-BI-Darstellung wird separat der neue PBIP-Quellentwurf geliefert.</div></main>
<script>
'use strict';
const DATA=__DATA__;
const INCIDENTS=__INCIDENTS__;
const WMS=__WMS__;
const $=id=>document.getElementById(id);
const escapeHTML=v=>String(v==null?'':v).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const int=v=>Number(v)||0;
let filtered=[],page=0,selected=null;
let REVIEWS={};
try{REVIEWS=JSON.parse(localStorage.getItem('P1_PHASE6_LOCAL_REVIEWS')||'{}')}catch(_){REVIEWS={}}
function saveLocal(){try{localStorage.setItem('P1_PHASE6_LOCAL_REVIEWS',JSON.stringify(REVIEWS))}catch(_){}}

for(const g of [...new Set(DATA.map(x=>x.product_group))].sort()){const el=document.createElement('option');el.value=g;el.textContent=g;$('group').append(el)}
function draw(){const q=$('search').value.trim().toLowerCase(),g=$('group').value,p=$('priority').value,only=$('onlySignal').checked;
filtered=DATA.filter(r=>(!g||r.product_group===g)&&(!p||r.priority_code===p)&&(!only||int(r.review_domain_count)>0)&&(!q||[r.sku,r.product_group,r.review_domains,r.dq01_status,r.dq02_status,r.dq06_status,r.next_step_proposal].join(' ').toLowerCase().includes(q)));
filtered.sort((a,b)=>(a.priority_sort===b.priority_sort?0: (priorityOrder(a.priority_code)-priorityOrder(b.priority_code)))||b.review_domain_count-a.review_domain_count||a.sku.localeCompare(b.sku));
const tally=fn=>filtered.filter(fn).length;
$('k-total').textContent=filtered.length;$('k-signal').textContent=tally(r=>int(r.review_domain_count)>0);
$('k-p1').textContent=tally(r=>int(r.release_migration_conflict)>0);
$('k-unassigned').textContent=tally(r=>int(r.needs_case_review)>0);
$('k-clean').textContent=tally(r=>int(r.review_domain_count)===0);
$('table-count').textContent=filtered.length+' Artikel im Filter';
const bars=$('bars');bars.replaceChildren();const c=Object.fromEntries(['P1','P2','P3','P0'].map(k=>[k,tally(r=>r.priority_code===k)]));const mx=Math.max(1,...Object.values(c));
for(const k of ['P1','P2','P3','P0']){const row=document.createElement('div');row.className='bar';row.innerHTML='<span class="barlabel">'+escapeHTML(k)+'</span><div class="track"><div class="fill" style="width:'+((c[k]/mx)*100)+'%"></div></div><span class="barvalue mono">'+c[k]+'</span>';bars.appendChild(row)}
if(page*35>=filtered.length)page=0;const start=page*35,part=filtered.slice(start,start+35);$('body').replaceChildren();
for(const r of part){const tr=document.createElement('tr');tr.dataset.sku=r.sku;if(r.sku===selected)tr.className='selected';tr.innerHTML='<td class="mono">'+escapeHTML(r.sku)+'</td><td><span class="pill '+r.priority_code.toLowerCase()+'">'+escapeHTML(r.priority_code)+'</span></td><td>'+escapeHTML(r.dq01_status)+'</td><td>'+escapeHTML(r.dq02_status)+'</td><td>'+escapeHTML(r.dq06_status)+'</td><td>'+escapeHTML(r.review_domains||'—')+'</td><td>'+escapeHTML(r.sku_linked_cases)+'</td>';tr.onclick=()=>{selected=r.sku;renderDetail(r);draw();};$('body').appendChild(tr)}
$('pagination').textContent=filtered.length?((start+1)+'–'+(start+part.length)+' / '+filtered.length):'Keine Treffer';$('prev').disabled=page<=0;$('next').disabled=(page+1)*35>=filtered.length;
if(selected&&!filtered.some(r=>r.sku===selected)){selected=null;$('detail').textContent='Wähle einen Artikel aus der aktuellen Filterauswahl.';$('review-form').style.display='none'}
}
function priorityOrder(x){return ({P1:0,P2:1,P3:2,P0:3})[x]??4}
function renderDetail(r){
$('review-form').style.display='block';
$('review-status').value=(REVIEWS[r.sku]||{}).status||'NEU';
$('review-note').value=(REVIEWS[r.sku]||{}).note||'';
$('review-message').textContent='Nur lokale Notiz – ändert keine ERP-, WMS- oder Incident-Quelldaten.';
let fields=[['SKU',r.sku],['Priorität',r.priority],['Produktgruppe',r.product_group],['Migration',r.dq01_status],['Dimension',r.dq02_status],['Freigaberegistrierung',r.dq06_status],['Prüfdomänen',r.review_domains||'Keine'],['SKU-bezogene Fälle',r.sku_linked_cases],['Vorgeschlagener Owner',r.owner_proposal],['Nächster Schritt',r.next_step_proposal]];$('detail').innerHTML=fields.map(([a,b])=>'<div class="details-row"><span>'+escapeHTML(a)+'</span><strong>'+escapeHTML(b)+'</strong></div>').join('')}
function renderStage(){const r=INCIDENTS.find(x=>x.stage===$('stage').value);const ratio=(Number(r.pass_ratio)*100).toLocaleString('de-DE',{minimumFractionDigits:2,maximumFractionDigits:2});$('incident').innerHTML='<div class="eyebrow">'+(r.stage==='BEFORE'?'Vorher · S2':'Nachher · S3')+'</div><div class="test mono">'+escapeHTML(r.actual_length_mm)+' mm <span class="hint">/ Soll: '+escapeHTML(r.expected_length_mm)+' mm</span></div><p>DQ02: <strong>'+escapeHTML(r.dq02_status)+'</strong><br>Konsistenz: <strong>'+ratio+' % ('+escapeHTML(r.pass_count)+'/'+escapeHTML(r.evaluable_count)+')</strong><br>WMS: <strong>'+escapeHTML(r.wms_dependent_retest_status)+'</strong><br>Incident: <strong>'+escapeHTML(r.incident_status)+'</strong></p>';
$('wmsevidence').textContent='Simulierter WMS-Testnachweis: '+WMS[0].retest_id+', '+WMS[0].ack_status+' ('+WMS[0].checked_at+'). Nur für S3 gültig.'}
for(const id of ['search','group','priority','onlySignal'])$(id).addEventListener(id==='search'?'input':'change',()=>{page=0;draw()});
$('save-review').onclick=()=>{if(!selected)return;REVIEWS[selected]={status:$('review-status').value,note:$('review-note').value};saveLocal();$('review-message').textContent='Prüfstand lokal gespeichert; mit CSV exportierbar. Kein Incident automatisch geschlossen.'};
$('reset').onclick=()=>{ $('review-form').style.display='none';$('search').value='';$('group').value='';$('priority').value='';$('onlySignal').checked=false;selected=null;page=0;$('detail').textContent='Wähle links einen Artikel aus.';draw()};
$('prev').onclick=()=>{page=Math.max(0,page-1);draw()};$('next').onclick=()=>{page+=1;draw()};$('stage').addEventListener('change',renderStage);
$('export').onclick=()=>{const cols=[...Object.keys(DATA[0]),'local_review_status','local_review_note'];const value=v=>'"'+String(v??'').replaceAll('"','""')+'"';const lines=[cols.map(value).join(';'),...filtered.map(r=>cols.map(k=>value(k==='local_review_status'?((REVIEWS[r.sku]||{}).status||'NEU'):k==='local_review_note'?((REVIEWS[r.sku]||{}).note||''):r[k])).join(';'))];const blob=new Blob(['\uFEFF'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Phase6_Aktionsliste_gefiltert.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)};
draw();renderStage();
</script></body></html>'''
page=page.replace('__DATA__',js(rows)).replace('__INCIDENTS__',js(inc)).replace('__WMS__',js(wms))
out=P/'powerbi/Phase6_DataQuality_CommandCenter_OFFLINE.html';out.write_text(page,encoding='utf8')
print('HTML',out,len(page))
